// `btrmnt publish` and `btrmnt promote`.
//
// publish:
//   1. CWD must be a git repo with a `btrmnt` remote.
//   2. `git add -A`
//   3. If anything is staged, commit it ("<msg>" or autogenerated).
//   4. `git push btrmnt main` (add `--force` when `force` is set) — using
//      `http.extraHeader=Cookie: CF_Authorization=<jwt>` so CF Access at the
//      edge authenticates the git-over-HTTPS connection the same way it
//      authenticates the API.
//   5. Print {sha, message}.
//
// `--force` is the escape hatch for a divergent history (e.g. republishing
// after a delete+recreate left the remote with unrelated commits). The
// git-server accepts non-fast-forward updates, so a force push replaces main.
//
// promote:
//   1. Resolve slug from --project flag or from CWD's `btrmnt` remote URL.
//   2. POST /v1/projects/<slug>/promote.
//   3. Print the returned ProjectEnvironment.

import { existsSync } from 'node:fs'
import { resolve } from 'node:path'
import { simpleGit } from 'simple-git'

import { ApiClient } from '../api.js'
import { resolveApiEndpoint, resolveCwd } from '../config.js'
import { readCredentials } from '../credentials.js'
import { authenticatedPush } from '../git-auth.js'
import { writeStderrJson, writeStdout } from '../output.js'
import { assertNoSecrets, candidatePathsFromGit, SecretFoundError } from '../secret-guard.js'

export async function publish(args: {
  message?: string
  apiEndpoint?: string
  allowSecrets?: boolean
  force?: boolean
}): Promise<void> {
  const cwd = resolveCwd()
  if (!existsSync(resolve(cwd, '.git'))) {
    throw new Error(`not a git repository: ${cwd}`)
  }
  const git = simpleGit(cwd)
  const remotes = await git.getRemotes(true)
  const btrmnt = remotes.find((r) => r.name === 'btrmnt')
  if (!btrmnt) {
    throw new Error(
      `no \`btrmnt\` remote configured in ${cwd}. Run \`btrmnt project new\` first.`,
    )
  }

  // Pre-commit secret scan. Same logic as `project new` — runs before
  // `git add .` so we never stage `.env`, AWS keys, or SSH private keys.
  // Scoped to files git would actually pick up (skips gitignored paths).
  const candidates = await candidatePathsFromGit(git)
  try {
    assertNoSecrets(cwd, candidates)
  } catch (err) {
    if (err instanceof SecretFoundError && args.allowSecrets) {
      writeStderrJson({
        warning: 'secret-guard bypassed via --allow-secrets',
        matches: err.matches,
      })
    } else {
      throw err
    }
  }

  await git.add('.')
  const status = await git.status()
  let sha = ''
  let message = args.message
  if (status.staged.length > 0) {
    if (!message || message.trim().length === 0) {
      message = `publish ${new Date().toISOString()}`
    }
    const result = await git.commit(message)
    sha = result.commit
  } else {
    // Nothing to commit — push whatever's at HEAD.
    const log = await git.log(['-1'])
    sha = log.latest!.hash
    message = log.latest!.message
  }

  // Send the CF Access JWT via env-driven git config so the bearer token
  // never appears on argv (no `ps` leak). See bin/src/git-auth.ts for the
  // full rationale (cookie + assertion variants, GIT_CONFIG_COUNT).
  const creds = readCredentials()
  await authenticatedPush({
    cwd,
    remote: 'btrmnt',
    branch: 'main',
    token: creds.token,
    ...(args.force ? { force: true } : {}),
  })

  // Try to look up the project so we can echo the test URL. Best-effort; we
  // don't fail publish if the api call fails.
  let testUrl: string | null = null
  try {
    const endpoint = args.apiEndpoint ?? creds.api_endpoint ?? resolveApiEndpoint()
    const slug = slugFromRemote(btrmnt.refs.push)
    if (slug) {
      const list = await new ApiClient(endpoint, creds.token).listProjects()
      const found = list.find((p) => p.slug === slug)
      testUrl = found?.environments.find((e) => e.env === 'test')?.url ?? null
    }
  } catch {
    // swallow — the push succeeded, that's the contract.
  }

  // Resolve the full SHA (simple-git may return an abbreviated hash on commit).
  if (sha && sha.length < 40) {
    try {
      sha = (await git.revparse(['HEAD'])).trim()
    } catch {
      // leave as-is
    }
  }

  writeStdout({ ok: true, sha, message, test_url: testUrl })
}

export async function promote(args: {
  project?: string
  apiEndpoint?: string
}): Promise<void> {
  const slug = await resolveSlugFromArgsOrCwd(args.project)
  const creds = readCredentials()
  const endpoint = args.apiEndpoint ?? creds.api_endpoint ?? resolveApiEndpoint()
  const client = new ApiClient(endpoint, creds.token)
  const env = await client.promote(slug)
  writeStdout(env)
}

export async function rollback(args: {
  project?: string
  to: string
  apiEndpoint?: string
}): Promise<void> {
  if (!/^[0-9a-f]{40}$/.test(args.to)) {
    throw new Error('--to must be a 40-char hex commit id')
  }
  const slug = await resolveSlugFromArgsOrCwd(args.project)
  const creds = readCredentials()
  const endpoint = args.apiEndpoint ?? creds.api_endpoint ?? resolveApiEndpoint()
  const client = new ApiClient(endpoint, creds.token)
  const env = await client.rollback(slug, args.to)
  writeStdout(env)
}

async function resolveSlugFromArgsOrCwd(explicit?: string): Promise<string> {
  if (explicit) return explicit
  const cwd = resolveCwd()
  if (!existsSync(resolve(cwd, '.git'))) {
    throw new Error(`not a git repository: ${cwd}; pass --project <slug> instead`)
  }
  const git = simpleGit(cwd)
  const remotes = await git.getRemotes(true)
  const btrmnt = remotes.find((r) => r.name === 'btrmnt')
  if (!btrmnt) {
    throw new Error('no `btrmnt` remote in CWD; pass --project <slug> instead')
  }
  const slug = slugFromRemote(btrmnt.refs.push)
  if (!slug) {
    throw new Error(`could not parse a project slug from ${btrmnt.refs.push}`)
  }
  return slug
}

/**
 * Pull a slug out of a remote URL like:
 *   https://api.btrmntlab.com/git/<tenant>/<slug>.git
 *   file:///tmp/.../<slug>.git
 *   file://C:\Users\...\<slug>.git           (Windows file URLs may carry backslashes)
 *   git@host:tenant/slug.git
 */
export function slugFromRemote(url: string): string | null {
  const m = url.match(/[\/\\]([a-z][a-z0-9-]{0,40}[a-z0-9])\.git$/)
  if (m) return m[1]!
  // Fallback for short paths (no .git suffix).
  const m2 = url.match(/[\/\\]([a-z][a-z0-9-]{0,40}[a-z0-9])[\/\\]?$/)
  if (m2) return m2[1]!
  return null
}
